"""Builders for S9 tests: evaluations that need the cloud, regions, and a pipeline-services stub.

Everything is synthetic and generated by code, so CI needs no `reference/` samples.
"""

from __future__ import annotations

from collections.abc import Callable, Sequence
from dataclasses import dataclass, field

from backend.adapters.fakes import FakeLearningStore, FakeSenders, FixedClock
from backend.core.models import (
    Box,
    Candidate,
    FieldKey,
    NormalizedPage,
    OcrWord,
    ReaderName,
    Region,
    RegionKind,
    SenderSpec,
    SourceKind,
)
from backend.core.pipeline.orchestrator import PipelineConfig
from backend.core.pipeline.s8_score import FieldEvaluation, evaluate_field
from backend.core.pipeline.s9_escalate import Escalation, escalate
from backend.core.ports.imaging import ImagingPort
from backend.core.ports.storage import StoragePort
from backend.core.ports.vision_llm import VisionLLMPort
from backend.core.scoring import DEFAULT_WEIGHTS
from backend.settings import Settings
from backend.tests.fixtures.layout import region, row
from backend.tests.fixtures.synthetic.pipeline_doubles import (
    PageScriptedBarcode,
    PageScriptedOcr,
    PageScriptedRegions,
)

CLOCK = FixedClock()
PATIENT: Box = (0.20, 0.10, 0.50, 0.90)
CLINICAL: Box = (0.60, 0.10, 0.80, 0.90)
STICKER: Box = (0.05, 0.60, 0.12, 0.95)
STAMP: Box = (0.85, 0.50, 0.95, 0.95)
NAME_BOX: Box = (0.30, 0.50, 0.35, 0.80)  # inside the patient box
ID_BOX: Box = (0.38, 0.50, 0.43, 0.80)  # inside the patient box


def weak(key: FieldKey, box: Box | None, *, value: str = "דנה") -> FieldEvaluation:
    """A field read once, by a handwriting-weak reader: low score, needs the cloud."""
    cand = Candidate(
        value=value,
        reader=ReaderName.tesseract,
        source=SourceKind.handwritten,
        box=box,
        reader_confidence=0.4,
        label_distance=0.1,
        region=RegionKind.patient_box,
    )
    return evaluate_field(key, [cand], spec=None, clock=CLOCK, weights=DEFAULT_WEIGHTS)


def missing(key: FieldKey) -> FieldEvaluation:
    """A field with no candidate at all: level D `not_found`, score 0."""
    return evaluate_field(key, [], spec=None, clock=CLOCK, weights=DEFAULT_WEIGHTS)


def standard_regions(*, clinical: bool = True) -> list[Region]:
    found = [
        region(RegionKind.patient_box, PATIENT),
        region(RegionKind.central_sticker, STICKER),
        region(RegionKind.receipt_stamp, STAMP),
    ]
    if clinical:
        found.append(region(RegionKind.clinical, CLINICAL))
    return found


def run_s9(
    vision: VisionLLMPort | None,
    evaluations: dict[FieldKey, FieldEvaluation],
    *,
    page: NormalizedPage,
    regions: Sequence[Region],
    settings: Settings,
    imaging: ImagingPort,
    storage: StoragePort,
    page_role: str | None = "primary",
    spec: SenderSpec | None = None,
    cloud_allowed: bool = True,
    config: PipelineConfig | None = None,
) -> Escalation:
    cfg = config or PipelineConfig()
    return escalate(
        evaluations,
        page=page,
        regions=regions,
        page_role=page_role,
        spec=spec,
        vision=vision,
        imaging=imaging,
        storage=storage,
        clock=CLOCK,
        settings=settings,
        weights=cfg.weights,
        scoring=cfg.scoring,
        measurement=page.measurement,
        config=cfg.escalation,
        prompt_version="v1",
        cloud_allowed=cloud_allowed,
    )


def filler_words(count: int = 20) -> list[OcrWord]:
    """Enough ordinary words that S5 does not classify the page as blank."""
    rows = [
        row(0.10 + 0.02 * i, ["שלום", "עולם", "בדיקה", "טקסט", "רגיל"]) for i in range(count // 5)
    ]
    return [w for r in rows for w in r]


class EveryPage(dict):  # type: ignore[type-arg]
    """A scripted-by-page-id mapping that answers the same for every page id."""

    def __init__(self, make: Callable[[], object]) -> None:
        super().__init__()
        self._make = make

    def get(self, key: object, default: object = None) -> object:
        return self._make()


def pipeline_services(
    settings: Settings,
    storage: StoragePort,
    imaging: ImagingPort,
    vision: VisionLLMPort | None,
    page_id: str,
    *,
    documents: object | None = None,
    any_page: bool = False,
) -> Services:
    """Services whose page `page_id` (or, with `any_page`, every page) has words and the standard
    regions but no barcode and no sender, so every field is unresolved and escalates."""
    words: dict[str, list[OcrWord]] = (
        EveryPage(filler_words) if any_page else {page_id: filler_words()}
    )
    regions: dict[str, list[Region]] = (
        EveryPage(standard_regions) if any_page else {page_id: standard_regions()}
    )
    return Services(
        settings=settings,
        ocr_printed=PageScriptedOcr(words=words),
        barcode=PageScriptedBarcode(),
        regions=PageScriptedRegions(regions=regions),
        vision=vision,
        storage=storage,
        documents=documents,
        imaging=imaging,
    )


@dataclass
class Services:
    """A PipelineServices for `process_page` tests: scripted OCR/barcode/regions, real storage
    and imaging, fake senders and learning. `vision` is whatever the test supplies."""

    settings: Settings
    ocr_printed: object
    barcode: object
    regions: object
    vision: VisionLLMPort | None
    storage: StoragePort
    documents: object
    imaging: ImagingPort
    ocr_digits: object | None = None
    learning: FakeLearningStore = field(default_factory=FakeLearningStore)
    clock: FixedClock = field(default_factory=FixedClock)
    senders: FakeSenders = field(default_factory=FakeSenders)
    logo: object | None = None
    pipeline: PipelineConfig = field(default_factory=PipelineConfig)
